<?php
declare(strict_types=1);
namespace App\Services;
final class ModuleManifestValidator { private const STATUSES=['active','inactive','deploying'];private const CAPABILITIES=['sso','client_provisioning','remote_updates','health_check'];public function __construct(private readonly ModuleEndpointPolicy $policy){}public function validate(array $data,string $challenge,string $expectedProduct):array{if(array_diff(array_keys($data),['protocol','protocol_version','challenge','module','capabilities','connection','signature_algorithm','signature','public_key_fingerprint']))$this->bad();if(($data['protocol']??'')!=='gda-module-attach'||($data['protocol_version']??null)!==1||!hash_equals($challenge,(string)($data['challenge']??'')))$this->bad();$module=$data['module']??null;$capabilities=$data['capabilities']??null;$connection=$data['connection']??null;if(!is_array($module)||!is_array($capabilities)||!is_array($connection))$this->bad();if(array_diff(array_keys($module),['product','name','full_name','description','version','status','category','public_url','admin_url','icon'])||array_diff(array_keys($connection),['module_instance_id','attached_at','key_consumed']))$this->bad();foreach(['product','name','full_name','description','version','status','category','public_url','admin_url','icon'] as $field)if(!is_string($module[$field]??null)||trim($module[$field])==='')$this->bad();if($module['product']!==$expectedProduct||!preg_match('/^gda-[a-z0-9]+(?:-[a-z0-9]+)*$/',$module['product']))$this->bad();if(!preg_match('/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/',$module['version'])||!in_array($module['status'],self::STATUSES,true))$this->bad();foreach(['name'=>150,'full_name'=>190,'description'=>2000,'category'=>100,'icon'=>50] as $field=>$max)if(mb_strlen($module[$field])>$max)$this->bad();$this->policy->assertAllowed($module['public_url']);$this->policy->assertAllowed($module['admin_url']);if(array_diff(array_keys($capabilities),self::CAPABILITIES))$this->bad();foreach(self::CAPABILITIES as $capability)if(!array_key_exists($capability,$capabilities)||!is_bool($capabilities[$capability]))$this->bad();if(!is_string($connection['module_instance_id']??null)||!preg_match('/^[A-Za-z0-9_-]{12,190}$/',$connection['module_instance_id'])||($connection['key_consumed']??null)!==true)$this->bad();if(!is_string($connection['attached_at']??null)||strtotime($connection['attached_at'])===false)$this->bad();foreach(['signature_algorithm','signature','public_key_fingerprint'] as $field)if(isset($data[$field])&&!is_string($data[$field]))$this->bad();return ['module'=>$module,'capabilities'=>$capabilities,'connection'=>$connection,'signature_algorithm'=>$data['signature_algorithm']??null,'signature'=>$data['signature']??null,'public_key_fingerprint'=>$data['public_key_fingerprint']??null];}private function bad():never{throw new ModuleAttachmentException('incompatible_manifest','A resposta do módulo é incompatível.');} }
